def kth_implicit_game_character(k,operations):
    length=1;used=0
    while length<k:length*=2;used+=1
    shifts=0
    while length>1:
        if k>length//2:k-=length//2;shifts+=operations[used-1]
        length//=2;used-=1
    return chr(ord('a')+shifts%26)

